# OpenMT2 client packages.
#
# Ordered list of repositories cloned from the open-mt2 organization into
# src/<directory>. The order is important: it is also the order in which the
# root CMakeLists.txt adds the packages, so dependencies must come first.
#
# Format: <github-repository>=<source-directory>
pkg_eterbase=EterBase
pkg_eterlocale=EterLocale
pkg_eterpack=EterPack
pkg_eterimagelib=EterImageLib
pkg_spherelib=SphereLib
pkg_cwebbrowser=CWebBrowser
pkg_eterlib=EterLib
pkg_mileslib=MilesLib
pkg_etergrnlib=EterGrnLib
pkg_speedtreelib=SpeedTreeLib
pkg_prterrainlib=PRTerrainLib
pkg_effectlib=EffectLib
pkg_scriptlib=ScriptLib
pkg_eterpythonlib=EterPythonLib
pkg_gamelib=GameLib
pkg_userinterface=UserInterface
